<?php $page='projects';require __DIR__.'/_head.php';$msg='';$edit=null;if(isset($_GET['edit'])){$st=db()->prepare('SELECT * FROM projects WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');if(!$title)throw new RuntimeException('Title required.');$slug=slugify($_POST['slug']?:$title);$image=upload_image('image','uploads/projects');if($id){$old=db()->prepare('SELECT image_url FROM projects WHERE id=?');$old->execute([$id]);$old=$old->fetch();$sql='UPDATE projects SET title=?,slug=?,category=?,description=?,tech_stack=?,live_url=?,github_url=?,featured=?,sort_order=?'.($image?',image_url=?':'').' WHERE id=?';$args=[$title,$slug,trim($_POST['category']??''),trim($_POST['description']??''),trim($_POST['tech_stack']??''),trim($_POST['live_url']??''),trim($_POST['github_url']??''),(int)isset($_POST['featured']),(int)$_POST['sort_order']];if($image)$args[]=$image;$args[]=$id;db()->prepare($sql)->execute($args);if($image)delete_upload($old['image_url']??null);$msg='Project updated.';}else{db()->prepare('INSERT INTO projects(title,slug,category,description,tech_stack,image_url,live_url,github_url,featured,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$title,$slug,trim($_POST['category']??''),trim($_POST['description']??''),trim($_POST['tech_stack']??''),$image,trim($_POST['live_url']??''),trim($_POST['github_url']??''),(int)isset($_POST['featured']),(int)$_POST['sort_order']]);$msg='Project added.';}$edit=null;}catch(Throwable $e){$msg=$e->getMessage();}if(isset($_GET['delete'])){}}if(isset($_GET['delete'])){check_csrf();$st=db()->prepare('SELECT image_url FROM projects WHERE id=?');$st->execute([(int)$_GET['delete']]);$old=$st->fetch();db()->prepare('DELETE FROM projects WHERE id=?')->execute([(int)$_GET['delete']]);delete_upload($old['image_url']??null);header('Location:projects.php');exit;}$rows=db()->query('SELECT * FROM projects ORDER BY sort_order,id DESC')->fetchAll();?><div class="topbar"><h1>Projects</h1></div><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><h2><?=$edit?'Edit project':'Add project'?></h2><form class="form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="row"><label>Title<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>Slug<input name="slug" value="<?=e($edit['slug']??'')?>"></label></div><div class="row"><label>Category<input name="category" value="<?=e($edit['category']??'')?>"></label><label>Tech stack<input name="tech_stack" value="<?=e($edit['tech_stack']??'')?>"></label></div><label>Description<textarea name="description"><?=e($edit['description']??'')?></textarea></label><div class="row"><label>Live URL<input name="live_url" value="<?=e($edit['live_url']??'')?>"></label><label>GitHub URL<input name="github_url" value="<?=e($edit['github_url']??'')?>"></label></div><div class="row"><label>Project image upload<input type="file" name="image" accept="image/*"></label><label>Order<input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label></div><label><input type="checkbox" name="featured" <?=$edit&&$edit['featured']?'checked':''?>> Featured project</label><button class="btn primary">Save project</button></form></div><div class="panel" style="margin-top:20px"><h2>All projects</h2><table class="table"><tr><th>Image</th><th>Title</th><th>Featured</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?php if($r['image_url']):?><img class="thumb" src="../<?=e($r['image_url'])?>"><?php endif;?></td><td><b><?=e($r['title'])?></b><div class="muted"><?=e($r['tech_stack'])?></div></td><td><?=((int)$r['featured']?'Yes':'No')?></td><td class="actions"><a class="btn" href="?edit=<?=$r['id']?>">Edit</a><a class="btn danger" onclick="return confirm('Delete project?')" href="?delete=<?=$r['id']?>&csrf=<?=e(csrf())?>">Delete</a></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/_foot.php';
